    addBox(14,6,15,x,16,z,0xe0ebea);
    addBox(w-4,.8,d-7,x,13.5,z,0x72a9b5);
    addBox(4,.4,.35,x,19,z+(d-7)/2+.3,0xc74449);
    addBox(.4,4,.35,x,19,z+(d-7)/2+.3,0xc74449);
