    const d=[7.4,12.9,9.4,9.4,7.4,6.8,11.6,7.9,14.2,11.2,10.5,9.4][shape]*(.9+rnd(seed*37+3)*.12);
    const height=[4.2,5.1,5.2,6.4,4.7,4.0,5.0,4.5,9.0,6.8,12.2,4.3][shape]*(.88+rnd(seed*41+2)*.22)*(district==='centro'?1.08:1);
